        out_ld_a[(j*32 + lane)*2 + 1] = __bfloat162float(*reinterpret_cast<__nv_bfloat16*>(&hi));
    }
    for (int j = 0; j < 2; ++j) {
        uint16_t lo = (uint16_t)(b[j] & 0xffff), hi = (uint16_t)(b[j] >> 16);
        out_ld_b[(j*32 + lane)*2 + 0] = __bfloat162float(*reinterpret_cast<__nv_bfloat16*>(&lo));
        out_ld_b[(j*32 + lane)*2 + 1] = __bfloat162float(*reinterpret_cast<__nv_bfloat16*>(&hi));
